window.products.push({"id":911461,"name":"DJI Phantom 4 Battery Label Decals (Red)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51mOUamTe4L._AC_.jpg","description":"DJI Phantom vinyl window decal. This decal is 8.25\" wide and 3.75\" high and is made of high quality vinyl that will last for years. Installation instructions are included, its as easy as clean, peal, stick, rub, remove! The decal is available in white, black or red. If you are going to be installing the decal on a car window white is recommended. The decal can be installed on any smooth surface like carrying cases, laptops, doors etc.","images":["https://m.media-amazon.com/images/I/51mOUamTe4L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"The Ink Wall","source_asin":"B01FEVST48","category_path":"Home & Kitchen"},"sku":"BM-911461","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01FEVST48","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01FEVST48","price_pending":true,"merchant_ready":false});
